1	// JSON Pointer (RFC 6901) and JSON Patch (RFC 6902).
2	
3	const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);
4	const INDEX_RE = /^(0|[1-9][0-9]*)$/;
5	
6	export class PatchError extends Error {
7	  constructor(message, index) {
8	    super(message);
9	    this.name = 'PatchError';
10	    this.index = index;
11	  }
12	}
13	
14	export function parsePointer(pointer) {
15	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
16	  if (pointer === '') return [];
17	  if (pointer[0] !== '/' || /~(?![01])/.test(pointer)) throw new SyntaxError('invalid pointer');
18	  return pointer
19	    .slice(1)
20	    .split('/')
21	    .map((token) => token.replace(/~[01]/g, (m) => (m === '~0' ? '~' : '/')));
22	}
23	
24	function isObject(value) {
25	  return value !== null && typeof value === 'object' && !Array.isArray(value);
26	}
27	
28	// Defines an own data member, so names such as `__proto__` stay ordinary members.
29	function setMember(obj, name, value) {
30	  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
31	}
32	
33	function emptyLike(value) {
34	  if (Array.isArray(value)) return [];
35	  return isObject(value) ? {} : value;
36	}
37	
38	// Iterative deep copy of a JSON value: keeps -0 and member order, never recurses.
39	function deepCopy(value) {
40	  const root = emptyLike(value);
41	  const stack = root === value ? [] : [[value, root]];
42	  while (stack.length > 0) {
43	    const [src, dst] = stack.pop();
44	    const keys = Array.isArray(src) ? src.keys() : Object.keys(src);
45	    for (const key of keys) {
46	      const child = src[key];
47	      const copy = emptyLike(child);
48	      setMember(dst, key, copy);
49	      if (copy !== child) stack.push([child, copy]);
50	    }
51	  }
52	  return root;
53	}
54	
55	function jsonEqual(a, b) {
56	  const stack = [[a, b]];
57	  while (stack.length > 0) {
58	    const [x, y] = stack.pop();
59	    if (Array.isArray(x) || Array.isArray(y)) {
60	      if (!Array.isArray(x) || !Array.isArray(y) || x.length !== y.length) return false;
61	      for (let i = 0; i < x.length; i++) stack.push([x[i], y[i]]);
62	    } else if (isObject(x) || isObject(y)) {
63	      if (!isObject(x) || !isObject(y)) return false;
64	      const keys = Object.keys(x);
65	      if (keys.length !== Object.keys(y).length) return false;
66	      for (const key of keys) {
67	        if (!Object.hasOwn(y, key)) return false;
68	        stack.push([x[key], y[key]]);
69	      }
70	    } else if (x !== y) {
71	      return false;
72	    }
73	  }
74	  return true;
75	}
76	
77	class ApplyFailure extends Error {}
78	
79	// Returns the array index a token names on `arr`, or throws.
80	function arrayIndex(arr, token, notFound, allowEnd) {
81	  if (!INDEX_RE.test(token)) throw new ApplyFailure(token === '-' ? notFound : 'bad index');
82	  const index = Number(token);
83	  if (index < arr.length || (allowEnd && index === arr.length)) return index;
84	  throw new ApplyFailure(notFound);
85	}
86	
87	// Returns the value that `token` names on `value`, or throws.
88	function child(value, token, notFound) {
89	  if (Array.isArray(value)) return value[arrayIndex(value, token, notFound, false)];
90	  if (isObject(value) && Object.hasOwn(value, token)) return value[token];
91	  throw new ApplyFailure(notFound);
92	}
93	
94	function walk(root, tokens, notFound) {
95	  let value = root;
96	  for (const token of tokens) value = child(value, token, notFound);
97	  return value;
98	}
99	
100	function add(root, tokens, value) {
101	  if (tokens.length === 0) return value;
102	  const parent = walk(root, tokens.slice(0, -1), 'path not found');
103	  const last = tokens[tokens.length - 1];
104	  if (Array.isArray(parent)) {
105	    if (last === '-') parent.push(value);
106	    else parent.splice(arrayIndex(parent, last, 'path not found', true), 0, value);
107	  } else if (isObject(parent)) {
108	    setMember(parent, last, value);
109	  } else {
110	    throw new ApplyFailure('path not found');
111	  }
112	  return root;
113	}
114	
115	function remove(root, tokens, notFound) {
116	  const parent = walk(root, tokens.slice(0, -1), notFound);
117	  const last = tokens[tokens.length - 1];
118	  const value = child(parent, last, notFound);
119	  if (Array.isArray(parent)) parent.splice(Number(last), 1);
120	  else delete parent[last];
121	  return value;
122	}
123	
124	function replace(root, tokens, value) {
125	  if (tokens.length === 0) return value;
126	  const parent = walk(root, tokens.slice(0, -1), 'path not found');
127	  const last = tokens[tokens.length - 1];
128	  child(parent, last, 'path not found');
129	  setMember(parent, last, value);
130	  return root;
131	}
132	
133	function isProperPrefix(prefix, tokens) {
134	  return prefix.length < tokens.length && prefix.every((token, i) => token === tokens[i]);
135	}
136	
137	function tryParse(pointer) {
138	  if (typeof pointer !== 'string') return null;
139	  try {
140	    return parsePointer(pointer);
141	  } catch {
142	    return null;
143	  }
144	}
145	
146	// Checks one operation against the form rules; returns its parsed form or a reason string.
147	function checkOperation(op) {
148	  if (op === null || typeof op !== 'object' || Array.isArray(op)) return 'not an object';
149	  const name = Object.hasOwn(op, 'op') ? op.op : undefined;
150	  if (typeof name !== 'string' || !OPS.has(name)) return 'bad op';
151	  const path = Object.hasOwn(op, 'path') ? tryParse(op.path) : null;
152	  if (path === null) return 'bad path';
153	  const parsed = { name, path, pathString: op.path };
154	  if (name === 'move' || name === 'copy') {
155	    parsed.from = Object.hasOwn(op, 'from') ? tryParse(op.from) : null;
156	    if (parsed.from === null) return 'bad from';
157	    parsed.fromString = op.from;
158	  }
159	  if (name === 'add' || name === 'replace' || name === 'test') {
160	    if (!Object.hasOwn(op, 'value')) return 'missing value';
161	    parsed.value = op.value;
162	  }
163	  if (name === 'remove' && path.length === 0) return 'cannot remove root';
164	  if (name === 'move' && isProperPrefix(parsed.from, path)) return 'cannot move into own child';
165	  return parsed;
166	}
167	
168	function applyOperation(root, op) {
169	  switch (op.name) {
170	    case 'add':
171	      return add(root, op.path, deepCopy(op.value));
172	    case 'remove':
173	      remove(root, op.path, 'path not found');
174	      return root;
175	    case 'replace':
176	      return replace(root, op.path, deepCopy(op.value));
177	    case 'move': {
178	      if (op.fromString === op.pathString) {
179	        walk(root, op.from, 'from not found');
180	        return root;
181	      }
182	      const value = remove(root, op.from, 'from not found');
183	      return add(root, op.path, value);
184	    }
185	    case 'copy':
186	      return add(root, op.path, deepCopy(walk(root, op.from, 'from not found')));
187	    case 'test':
188	      if (!jsonEqual(walk(root, op.path, 'path not found'), op.value)) {
189	        throw new ApplyFailure('test failed');
190	      }
191	      return root;
192	  }
193	}
194	
195	export function applyPatch(doc, patch) {
196	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
197	  const ops = [];
198	  for (let i = 0; i < patch.length; i++) {
199	    const op = checkOperation(patch[i]);
200	    if (typeof op === 'string') throw new PatchError(`operation ${i}: ${op}`, i);
201	    ops.push(op);
202	  }
203	  let result = deepCopy(doc);
204	  for (let i = 0; i < ops.length; i++) {
205	    try {
206	      result = applyOperation(result, ops[i]);
207	    } catch (err) {
208	      if (err instanceof ApplyFailure) throw new PatchError(`operation ${i}: ${err.message}`, i);
209	      throw err;
210	    }
211	  }
212	  return result;
213	}
214

1	// Shared assertions for the jsonpatch tests (exports only, no tests).
2	import assert from 'node:assert/strict';
3	import { applyPatch, PatchError } from '../jsonpatch.mjs';
4	
5	// Deep equality that also checks member order, prototypes and -0 (Object.is).
6	export function assertExact(actual, expected, where = '$') {
7	  if (Array.isArray(expected)) {
8	    assert.ok(Array.isArray(actual), `${where}: expected an array`);
9	    assert.equal(actual.length, expected.length, `${where}: length`);
10	    expected.forEach((item, i) => assertExact(actual[i], item, `${where}[${i}]`));
11	    return;
12	  }
13	  if (expected !== null && typeof expected === 'object') {
14	    assert.ok(
15	      actual !== null && typeof actual === 'object' && !Array.isArray(actual),
16	      `${where}: expected an object`,
17	    );
18	    assert.equal(Object.getPrototypeOf(actual), Object.prototype, `${where}: prototype`);
19	    assert.deepEqual(Object.keys(actual), Object.keys(expected), `${where}: member names/order`);
20	    for (const key of Object.keys(expected)) {
21	      assert.ok(Object.hasOwn(actual, key), `${where}: own member ${key}`);
22	      assertExact(actual[key], expected[key], `${where}.${key}`);
23	    }
24	    return;
25	  }
26	  assert.ok(Object.is(actual, expected), `${where}: ${String(actual)} is not ${String(expected)}`);
27	}
28	
29	// Asserts applyPatch(doc, patch) throws a PatchError with exactly this message and index.
30	export function assertPatchError(doc, patch, message, index) {
31	  let caught;
32	  try {
33	    applyPatch(doc, patch);
34	  } catch (err) {
35	    caught = err;
36	  }
37	  assert.ok(caught !== undefined, `expected PatchError "${message}", nothing was thrown`);
38	  assert.ok(caught instanceof PatchError, `expected PatchError, got ${caught && caught.name}: ${caught && caught.message}`);
39	  assert.ok(caught instanceof Error);
40	  assert.equal(caught.name, 'PatchError');
41	  assert.equal(caught.message, message);
42	  assert.ok(Object.is(caught.index, index), `index ${String(caught.index)} is not ${String(index)}`);
43	}
44	
45	// Parses JSON text so names such as "__proto__" become own members, as JSON.parse does.
46	export const j = (text) => JSON.parse(text);
47	
48	// Collects every object and array reachable from a value.
49	export function containers(value, found = new Set()) {
50	  const stack = [value];
51	  while (stack.length > 0) {
52	    const current = stack.pop();
53	    if (current === null || typeof current !== 'object' || found.has(current)) continue;
54	    found.add(current);
55	    for (const key of Reflect.ownKeys(current)) stack.push(current[key]);
56	  }
57	  return found;
58	}
59	
60	// Asserts that no object or array of `result` is also reachable from any of `sources`.
61	export function assertNoSharing(result, ...sources) {
62	  const seen = new Set();
63	  for (const source of sources) containers(source, seen);
64	  for (const item of containers(result)) assert.ok(!seen.has(item), 'result shares an object with its inputs');
65	}
